/**
 * Where a recording's notes and beats begin, and the tempo they keep: what a
 * DAW reads off a file it is given, to play it in time (CLP-018, CLP-019).
 */
import type { WarpMarker } from "../time/warp";

/** How often the level is read, in seconds: fine enough to tell sixteenths apart at 200 BPM. */
const HOP_SECONDS = 0.005;
/** How long a stretch each reading of the level spans, in seconds: longer than the beating of notes held together (a chord's beat near 55 Hz), which would read as a slow pulse, and short enough to tell sixteenths apart. */
const WINDOW_SECONDS = 0.04;
/** How much of the level before it a rise must add to count: a held note's wavering stays under it. */
const RISE_SHARE = 0.25;
/** The slowest and fastest beat a tempo is looked for at. */
const MIN_BPM = 60;
const MAX_BPM = 200;
/** Two transients are this far apart at least, in seconds. */
const MIN_GAP_SECONDS = 0.05;
/** How far around a rise its local level is read, in seconds. */
const LOCAL_SECONDS = 0.25;

/** A recording's tempo, as `@audio/beat-detect` reads it and the registry's `analyzeBeat` fits it to the transients. */
export interface TempoEstimate {
  bpm: number;
  /** How much of the recording's rises fall on that beat, from 0 to 1. */
  confidence: number;
  /** Where its first beat falls, in seconds. */
  firstBeat: number;
}

/** How the level rises, read every `hop` frames over `window` frames: the rise of its RMS where it is a sound starting, so a loud hit counts for more than a soft one, and 0 elsewhere. */
function rises(
  channels: readonly Float32Array[],
  hop: number,
  window: number
): Float32Array {
  const length = channels[0]?.length ?? 0;
  const count = Math.max(0, Math.floor(length / hop));
  const squares = (from: number, to: number) => {
    let sum = 0;
    for (const channel of channels) {
      for (let index = from; index < to; index += 1) {
        sum += (channel[index] as number) ** 2;
      }
    }
    return sum;
  };
  // Each hop's squares, summed once: a window is the hops it covers, and the part of one where it starts. Read
  // afresh each time, a window's sum never carries the rounding of the windows before it, as a running one would.
  const hops = Float64Array.from({ length: count }, (_, index) =>
    squares(index * hop, (index + 1) * hop)
  );
  const level = new Float32Array(count);
  for (let frame = 0; frame < count; frame += 1) {
    // The stretch just before the reading: a sound that starts rises the level where it starts, not a window early.
    const to = (frame + 1) * hop;
    const from = Math.max(0, to - window);
    const whole = Math.ceil(from / hop);
    let sum = squares(from, whole * hop);
    for (let index = whole; index <= frame; index += 1) {
      sum += hops[index] as number;
    }
    level[frame] = Math.sqrt(sum / ((to - from) * channels.length || 1));
  }
  const strength = new Float32Array(count);
  for (let frame = 1; frame < count; frame += 1) {
    const before = level[frame - 1] as number;
    const rise = (level[frame] as number) - before;
    // A held sound wavers a little; only a rise of a share of the level before it is a sound starting.
    strength[frame] = rise > RISE_SHARE * before ? rise : 0;
  }
  return strength;
}

const hopOf = (sampleRate: number) =>
  Math.max(1, Math.round(sampleRate * HOP_SECONDS));

/**
 * Where `channels` have their transients, in seconds: each frame where the
 * level rises sharply above what it does around it, found to the sample
 * where the slope first reaches half its height there.
 */
export function detectTransients(
  channels: readonly Float32Array[],
  sampleRate: number
): number[] {
  const hop = hopOf(sampleRate);
  const strength = rises(
    channels,
    hop,
    Math.round(sampleRate * WINDOW_SECONDS)
  );
  const count = strength.length;
  let highest = 0;
  for (const value of strength) {
    highest = Math.max(highest, value);
  }
  if (highest <= 0) {
    return [];
  }
  const reach = Math.max(1, Math.round(LOCAL_SECONDS / HOP_SECONDS));
  const peakReach = Math.max(1, Math.round(MIN_GAP_SECONDS / HOP_SECONDS));
  const found: number[] = [];
  let last = Number.NEGATIVE_INFINITY;
  for (let frame = 1; frame < count; frame += 1) {
    const value = strength[frame] as number;
    let sum = 0;
    let isPeak = value > 0;
    const from = Math.max(0, frame - reach);
    const to = Math.min(count, frame + reach + 1);
    for (let other = from; other < to; other += 1) {
      sum += strength[other] as number;
      if (
        Math.abs(other - frame) <= peakReach &&
        (strength[other] as number) > value
      ) {
        isPeak = false;
      }
    }
    const threshold = (1.5 * sum) / (to - from) + 0.1 * highest;
    if (isPeak && value > threshold && frame - last >= peakReach) {
      found.push(sampleOf(channels, frame, hop) / sampleRate);
      last = frame;
    }
  }
  return found;
}

/** The first frame around rise `frame` where the slope reaches half its height there. */
function sampleOf(
  channels: readonly Float32Array[],
  frame: number,
  hop: number
): number {
  const length = channels[0]?.length ?? 0;
  const from = Math.max(1, (frame - 1) * hop);
  const to = Math.min(length, (frame + 2) * hop);
  const slopeAt = (index: number) => {
    let most = 0;
    for (const channel of channels) {
      most = Math.max(
        most,
        Math.abs((channel[index] as number) - (channel[index - 1] as number))
      );
    }
    return most;
  };
  let peak = 0;
  for (let index = from; index < to; index += 1) {
    peak = Math.max(peak, slopeAt(index));
  }
  for (let index = from; index < to; index += 1) {
    if (slopeAt(index) >= peak / 2) {
      return index;
    }
  }
  return frame * hop;
}

/** How a file plays in time at an arrangement's tempo, as `autoWarp` works it out. */
export interface AutoWarp {
  /** The tempo it is taken to be at. */
  bpm: number;
  /** Where the clip starts in its own time: on the first beat. */
  offset: number;
  warp: WarpMarker[];
}

/** The bar counts a short file is taken to be a loop of. */
const LOOP_BARS = [1, 2, 4, 8, 16] as const;
/** How near the tempo a loop's length gives must be to the estimate, or to its double or half. */
const LOOP_TOLERANCE = 0.04;

/** How far apart two tempos are, as a share, once one is moved by octaves to the nearest of the other. */
function octaveDistance(a: number, b: number) {
  const octaves = Math.log2(a / b);
  return Math.abs(2 ** (octaves - Math.round(octaves)) - 1);
}

/**
 * The warp that plays a recording of `duration` seconds in time at `tempo`
 * BPM (CLP-019): a short one that a whole number of 1, 2, 4, 8 or 16 bars
 * fits at its estimated tempo, as that loop, marked at its start and end;
 * any other on a marker at the first beat of each bar, moved onto the
 * transient within an eighth of a beat. `null` when it has no tempo.
 */
export function autoWarp({
  beatsPerBar = 4,
  duration,
  estimate,
  tempo,
  transients = [],
}: {
  beatsPerBar?: number;
  duration: number;
  estimate: TempoEstimate | null;
  tempo: number;
  transients?: readonly number[];
}): AutoWarp | null {
  if (!estimate || duration <= 0 || tempo <= 0) {
    return null;
  }
  const loops = LOOP_BARS.map((bars) => (60 * beatsPerBar * bars) / duration)
    .filter(
      (loopBpm) =>
        loopBpm >= MIN_BPM / 2 &&
        loopBpm <= MAX_BPM * 2 &&
        octaveDistance(loopBpm, estimate.bpm) <= LOOP_TOLERANCE
    )
    .sort(
      (a, b) =>
        Math.abs(Math.log2(a / estimate.bpm)) -
        Math.abs(Math.log2(b / estimate.bpm))
    );
  const [loop] = loops;
  if (loop !== undefined) {
    return {
      bpm: loop,
      offset: 0,
      warp: [
        { source: 0, target: 0 },
        { source: duration, target: (duration * loop) / tempo },
      ],
    };
  }
  const { bpm, firstBeat } = estimate;
  const beat = 60 / bpm;
  const bar = beat * beatsPerBar;
  const targetBar = (60 * beatsPerBar) / tempo;
  const start = (firstBeat * bpm) / tempo;
  const warp: WarpMarker[] = [];
  for (let index = 0; firstBeat + index * bar < duration; index += 1) {
    const at = firstBeat + index * bar;
    const near = transients.reduce<number | null>(
      (closest, time) =>
        Math.abs(time - at) <= beat / 8 &&
        (closest === null || Math.abs(time - at) < Math.abs(closest - at))
          ? time
          : closest,
      null
    );
    warp.push({ source: near ?? at, target: start + index * targetBar });
  }
  if (warp.length === 1) {
    warp.push({
      source: duration,
      target: start + (duration - firstBeat) * (bpm / tempo),
    });
  }
  return { bpm, offset: start, warp };
}

/**
 * The transfer curve of a compressor: the output level in dB for each input
 * level in dB, the textbook curve with a knee centred on the threshold, what
 * a plug-in draws.
 */

export interface CompressorSettings {
  /** Width in dB of the soft bend around the threshold. @default 0 */
  kneeDb?: number;
  /** Gain added after compressing, in dB. @default 0 */
  makeupDb?: number;
  /** Input to output ratio above the threshold: 4 is 4:1. */
  ratio: number;
  thresholdDb: number;
}

/**
 * A compressor's transfer curve: the output level in dB for each input level
 * in dB. Below the threshold the level passes unchanged; above it, every
 * `ratio` dB in comes out as one, with a quadratic bend across the knee.
 */
export function compressorOutput({
  kneeDb = 0,
  makeupDb = 0,
  ratio,
  thresholdDb,
}: CompressorSettings): (inputDb: number) => number {
  const slope = 1 / Math.max(ratio, 1) - 1;
  const half = Math.max(kneeDb, 0) / 2;
  return (inputDb) => {
    const over = inputDb - thresholdDb;
    let reduction = 0;
    if (half > 0 && Math.abs(over) <= half) {
      reduction = (slope * (over + half) ** 2) / (4 * half);
    } else if (over > half) {
      reduction = slope * over;
    }
    return inputDb + reduction + makeupDb;
  };
}

/**
 * What a filter and an equalizer do to a signal, as the curve a plot draws: a
 * gain in dB at each frequency. Framework-agnostic and drawn from the formulas
 * an audio engine runs, the biquads of the RBJ "Audio EQ Cookbook", which the
 * Web Audio `BiquadFilterNode` implements: the curve equals the node's
 * `getFrequencyResponse` to rounding (checked against Chrome's, every type, Q
 * from 0.5 to 4), once `q` is passed to the node through `toWebAudioQ`.
 *
 * `q` is the cookbook's: linear, 1/sqrt(2) being the flat Butterworth. The node
 * reads it differently for two kinds of band, which `toWebAudioQ` and the
 * shelves below account for. The sample rate only decides where the top of the
 * curve bends toward Nyquist: 48 kHz is close enough for a picture (a 44.1 kHz
 * context differs by under 0.6 dB, at the very top), and a band can carry the
 * `sampleRate` of its context, such as `ctx.sampleRate`, to be exact.
 */

/** The sample rate a curve is drawn at unless a band says another. */
export const SAMPLE_RATE = 48_000;
const NYQUIST_SHARE = 0.49;
const MIN_Q = 0.05;
/** The quietest a magnitude is drawn, so a notch's null stays on the plot. */
const MIN_MAGNITUDE = 1e-9;

/** The kinds of band an equalizer draws: cuts, shelves, a peak, a notch and a band-pass. */
export type BiquadType =
  | "bandpass"
  | "highcut"
  | "highshelf"
  | "lowcut"
  | "lowshelf"
  | "notch"
  | "peak";

/** The Web Audio `BiquadFilterNode` type that does what each band type draws. */
export const WEB_AUDIO_FILTER_TYPES: Record<BiquadType, BiquadFilterType> = {
  bandpass: "bandpass",
  highcut: "lowpass",
  highshelf: "highshelf",
  lowcut: "highpass",
  lowshelf: "lowshelf",
  notch: "notch",
  peak: "peaking",
};

/**
 * The value to give a `BiquadFilterNode`'s `Q` for a band's `q`. The node takes
 * the Q of a low-pass or high-pass in decibels (`lowcut` and `highcut` here),
 * and a linear one for the other types, so `q` is converted for those two:
 * giving a `lowcut` of `q: 2` a `Q` of 2 would make it 2 dB, and the curve on
 * screen would not be the filter you hear. A shelf ignores Q in the node, and
 * so does its curve.
 */
export function toWebAudioQ(type: BiquadType, q = Math.SQRT1_2): number {
  if (type === "lowcut" || type === "highcut") {
    return 20 * Math.log10(Math.max(q, MIN_Q));
  }
  return q;
}

/** One filter as `biquadResponse` draws it: its type, frequency, gain and Q, at a sample rate. */
export interface BiquadSettings {
  frequency: number;
  /** Gain in dB: used by peaks and shelves, ignored by the rest. */
  gainDb?: number;
  /** The cookbook's Q, linear: 1/sqrt(2) is flat. Shelves have a fixed slope and ignore it. Pass it to a node with `toWebAudioQ`. @default Math.SQRT1_2 */
  q?: number;
  /** The sample rate the curve is drawn at, such as `ctx.sampleRate`. @default 48000 */
  sampleRate?: number;
  type: BiquadType;
}

interface Coefficients {
  a1: number;
  a2: number;
  b0: number;
  b1: number;
  b2: number;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

/** Coefficients divided by a0, from the cookbook. */
function coefficients({
  frequency,
  gainDb = 0,
  q: requestedQ = Math.SQRT1_2,
  sampleRate = SAMPLE_RATE,
  type,
}: BiquadSettings): Coefficients {
  // A shelf has the slope of 1 the Web Audio spec gives it, whatever the Q.
  const q =
    type === "lowshelf" || type === "highshelf" ? Math.SQRT1_2 : requestedQ;
  const w0 =
    (2 * Math.PI * clamp(frequency, 10, sampleRate * NYQUIST_SHARE)) /
    sampleRate;
  const cos = Math.cos(w0);
  const alpha = Math.sin(w0) / (2 * Math.max(q, MIN_Q));
  const a = 10 ** (gainDb / 40);
  const shelf = 2 * Math.sqrt(a) * alpha;

  let b: [number, number, number];
  let denominator: [number, number, number];
  switch (type) {
    case "lowshelf":
      b = [
        a * (a + 1 - (a - 1) * cos + shelf),
        2 * a * (a - 1 - (a + 1) * cos),
        a * (a + 1 - (a - 1) * cos - shelf),
      ];
      denominator = [
        a + 1 + (a - 1) * cos + shelf,
        -2 * (a - 1 + (a + 1) * cos),
        a + 1 + (a - 1) * cos - shelf,
      ];
      break;
    case "highshelf":
      b = [
        a * (a + 1 + (a - 1) * cos + shelf),
        -2 * a * (a - 1 + (a + 1) * cos),
        a * (a + 1 + (a - 1) * cos - shelf),
      ];
      denominator = [
        a + 1 - (a - 1) * cos + shelf,
        2 * (a - 1 - (a + 1) * cos),
        a + 1 - (a - 1) * cos - shelf,
      ];
      break;
    case "lowcut":
      b = [(1 + cos) / 2, -(1 + cos), (1 + cos) / 2];
      denominator = [1 + alpha, -2 * cos, 1 - alpha];
      break;
    case "highcut":
      b = [(1 - cos) / 2, 1 - cos, (1 - cos) / 2];
      denominator = [1 + alpha, -2 * cos, 1 - alpha];
      break;
    case "bandpass":
      b = [alpha, 0, -alpha];
      denominator = [1 + alpha, -2 * cos, 1 - alpha];
      break;
    case "notch":
      b = [1, -2 * cos, 1];
      denominator = [1 + alpha, -2 * cos, 1 - alpha];
      break;
    default:
      b = [1 + alpha * a, -2 * cos, 1 - alpha * a];
      denominator = [1 + alpha / a, -2 * cos, 1 - alpha / a];
  }
  const [a0, a1, a2] = denominator;
  return {
    a1: a1 / a0,
    a2: a2 / a0,
    b0: b[0] / a0,
    b1: b[1] / a0,
    b2: b[2] / a0,
  };
}

/** A biquad's gain in dB at `hz`, 0 being unity. */
export function biquadResponse(
  settings: BiquadSettings
): (hz: number) => number {
  const { a1, a2, b0, b1, b2 } = coefficients(settings);
  const sampleRate = settings.sampleRate ?? SAMPLE_RATE;
  return (hz) => {
    const omega = (2 * Math.PI * hz) / sampleRate;
    const numerator = Math.hypot(
      b0 + b1 * Math.cos(omega) + b2 * Math.cos(2 * omega),
      b1 * Math.sin(omega) + b2 * Math.sin(2 * omega)
    );
    const denominator = Math.hypot(
      1 + a1 * Math.cos(omega) + a2 * Math.cos(2 * omega),
      a1 * Math.sin(omega) + a2 * Math.sin(2 * omega)
    );
    if (denominator === 0) {
      return 0;
    }
    return 20 * Math.log10(Math.max(numerator / denominator, MIN_MAGNITUDE));
  };
}

/** One band of an equalizer: a filter that can be switched out of the chain. */
export interface EqBand extends BiquadSettings {
  /** Whether the band is in the chain. @default true */
  on?: boolean;
}

/** An equalizer's bands in series: their gains in dB add up at each frequency. */
export function eqResponse(bands: readonly EqBand[]): (hz: number) => number {
  const responses = bands
    .filter((band) => band.on !== false)
    .map((band) => biquadResponse(band));
  return (hz) => responses.reduce((db, response) => db + response(hz), 0);
}

/** A gain big enough to measure a band's effect at its own frequency without noise. */
const PROBE_DB = 12;

/**
 * Where a band's handle sits on an equalizer's curve: the response of all
 * the bands at the band's own frequency. A peak's handle is at its gain; a
 * shelf's is halfway up its slope; and other bands' reach adds to both.
 */
export function bandHandleDb(bands: readonly EqBand[], index: number): number {
  const band = bands[index];
  return band ? eqResponse(bands)(band.frequency) : 0;
}

/**
 * The inverse, for dragging: the gain a band needs at `frequency` for its
 * handle to sit at `responseDb` on the curve, so the handle follows the
 * pointer one to one instead of the gain drifting from it. A band that does
 * not take a gain (a cut, a notch) keeps the one it has.
 */
export function bandGainForHandle(
  bands: readonly EqBand[],
  index: number,
  frequency: number,
  responseDb: number
): number {
  const band = bands[index];
  if (!band) {
    return 0;
  }
  const others = eqResponse(bands.filter((_, at) => at !== index))(frequency);
  const share =
    biquadResponse({ ...band, frequency, gainDb: PROBE_DB })(frequency) /
    PROBE_DB;
  const own = biquadResponse({ ...band, frequency, gainDb: 0 })(frequency);
  if (Math.abs(share - own / PROBE_DB) < 0.05) {
    return band.gainDb ?? 0;
  }
  return (responseDb - others - own) / (share - own / PROBE_DB);
}

export {
  type AutoWarp,
  autoWarp,
  detectTransients,
  type TempoEstimate,
} from "./beat";
export {
  type CompressorSettings,
  compressorOutput,
} from "./compressor";
export {
  type BiquadSettings,
  type BiquadType,
  bandGainForHandle,
  bandHandleDb,
  biquadResponse,
  type EqBand,
  eqResponse,
  SAMPLE_RATE,
  toWebAudioQ,
  WEB_AUDIO_FILTER_TYPES,
} from "./filter";
export { dbToGain, gainToDb, peakDb, rmsDb } from "./level";
export {
  createLoudnessMeter,
  createLoudnessReader,
  type LiveLoudness,
  LOUDNESS_TARGETS,
  LOUDNESS_WORKLET,
  type Loudness,
  type LoudnessMeter,
  loudnessGain,
  measureLoudness,
} from "./loudness";
export {
  type AudioPeaks,
  computePeaks,
  downsampleWaveform,
  normalizePeaks,
  normalizeWaveform,
  type SpectrumBandsOptions,
  spectrumBands,
} from "./peaks";
export {
  type DetectPitchOptions,
  detectPitch,
  type PitchEstimate,
} from "./pitch";
export { analyzeBeat, audioChroma, type BeatAnalysis } from "./recording";
export {
  ACX,
  type AcxCheck,
  type AcxReport,
  checkAcx,
  reportSound,
  type SoundReport,
} from "./report";
export { detectSilences, type SilenceOptions } from "./silence";
export {
  SPECTRA_SIZE,
  type Spectra,
  type SpectraSource,
  spectrogramSpectra,
} from "./spectra";
export {
  holdPeaks,
  type LogSpectrumOptions,
  logSpectrum,
  type PeakHoldOptions,
  SPECTRUM_FLOOR_DB,
} from "./spectrum";
export { stereoCorrelation } from "./stereo";
export {
  type BandShares,
  type Bands,
  bandShares,
  createBandSplit,
  type SplitBands,
  splitBands,
} from "./tint";

/**
 * Levels, the way audio engines state them: a gain is a ratio of amplitudes,
 * so 20 dB per factor of ten, 6.02 dB per doubling, and 0 dB is full scale
 * (dBFS) or unity.
 */

/** The amplitude ratio of a level in dB: 0 dB is 1, -6.02 dB is 0.5. `0` for `-Infinity`. */
export function dbToGain(db: number): number {
  return 10 ** (db / 20);
}

/** The level in dB of an amplitude ratio: 1 is 0 dB, 0.5 is -6.02 dB. `-Infinity` for 0 or less, never `NaN`. */
export function gainToDb(gain: number): number {
  return gain > 0 ? 20 * Math.log10(gain) : Number.NEGATIVE_INFINITY;
}

/**
 * The RMS level of `samples` in dBFS: 0 dB for a square wave at full scale, -3
 * dB for a sine at full scale. `-Infinity` for silence, an empty array, or
 * one with a sample that is not a number.
 */
export function rmsDb(samples: Float32Array | readonly number[]): number {
  if (samples.length === 0) {
    return Number.NEGATIVE_INFINITY;
  }
  let sum = 0;
  for (const sample of samples) {
    sum += sample * sample;
  }
  return Number.isFinite(sum)
    ? gainToDb(Math.sqrt(sum / samples.length))
    : Number.NEGATIVE_INFINITY;
}

/**
 * The level in dBFS of the loudest sample of `samples`, either way: how near
 * the signal comes to clipping, where `rmsDb` says how loud it sounds. 0 dB
 * for a sample at full scale, `-Infinity` for silence, an empty array, or one
 * with a sample that is not a number.
 */
export function peakDb(samples: Float32Array | readonly number[]): number {
  let loudest = 0;
  for (const sample of samples) {
    loudest = Math.max(loudest, Math.abs(sample));
  }
  return Number.isFinite(loudest)
    ? gainToDb(loudest)
    : Number.NEGATIVE_INFINITY;
}

import { loadWorklet } from "../worklet/load";
/**
 * How loud a sound is, the way streaming services and broadcasters measure
 * it (ITU-R BS.1770): its integrated loudness in LUFS and its true peak in
 * dBTP, through `@audio/loudness-lufs` and `@audio/loudness-truepeak`, and the
 * gain that brings it to a target without passing a ceiling. And while it
 * plays: its momentary, short-term and integrated loudness, measured on the
 * audio thread through the K-weighting of `@audio/weighting-k`.
 */

import lufs from "@audio/loudness-lufs";
import truepeak from "@audio/loudness-truepeak";
import kWeighting from "@audio/weighting-k";
import { peakDb } from "./level";

/** Targets in LUFS: what streaming services, podcasts and broadcast (EBU R 128) ask a file to be. */
export const LOUDNESS_TARGETS = {
  broadcast: -23,
  podcast: -16,
  streaming: -14,
} as const;

/** How loud a sound is. Each is `-Infinity` for silence. */
export interface Loudness {
  /** Integrated loudness, in LUFS: over the whole sound, its quiet passages gated out. */
  lufs: number;
  /** The loudest sample, in dBFS. */
  peak: number;
  /** The loudest point of the waveform between the samples too, in dBTP: what a converter may play past full scale. */
  truePeak: number;
}

/**
 * Measures whole channels at once. It reads every sample, the true peak at
 * four points a sample: about half a second a minute of loud stereo on a
 * laptop, so call it where the page can wait, as an export does.
 */
export function measureLoudness(
  channels: readonly Float32Array[],
  sampleRate: number
): Loudness {
  if (channels.length === 0) {
    return {
      lufs: Number.NEGATIVE_INFINITY,
      peak: Number.NEGATIVE_INFINITY,
      truePeak: Number.NEGATIVE_INFINITY,
    };
  }
  return {
    lufs: lufs([...channels], { fs: sampleRate }) ?? Number.NEGATIVE_INFINITY,
    peak: Math.max(...channels.map((channel) => peakDb(channel))),
    truePeak: truepeak([...channels], { fs: sampleRate }),
  };
}

/**
 * The gain in dB that brings a sound to `target` LUFS, as far as its true
 * peak stays at or under `ceiling` dBTP: a sound that would pass it lands
 * under the target instead, and nothing is limited. 0 for silence.
 */
export function loudnessGain(
  loudness: Loudness,
  target: number,
  ceiling = -1
): number {
  if (!Number.isFinite(loudness.lufs)) {
    return 0;
  }
  return Math.min(target - loudness.lufs, ceiling - loudness.truePeak);
}

/** What BS.1770 adds to a K-weighted mean square to read it in LUFS. */
const OFFSET = -0.691;
/** The power of a 400 ms window at the absolute gate, -70 LUFS: anything quieter is silence. */
const ABSOLUTE_GATE = 10 ** ((-70 - OFFSET) / 10);
/** The relative gate, 10 LU under the loudness of what passed the absolute one, as a ratio of power. */
const RELATIVE_GATE = 10 ** (-10 / 10);
/** A window is 4 blocks of 100 ms: what momentary loudness reads, and what the gates count. */
const WINDOW_BLOCKS = 4;
/** Short-term loudness reads the last 3 s. */
const SHORT_TERM_BLOCKS = 30;

const lufsOf = (power: number) => OFFSET + 10 * Math.log10(power);
const mean = (powers: readonly number[]) =>
  powers.reduce((sum, power) => sum + power, 0) / powers.length;

/** How loud a sound is while it plays, in LUFS. Each is `-Infinity` until there is enough of the sound to read it, and for silence. */
export interface LiveLoudness {
  /** Over everything since the reader was cleared, its quiet passages gated out: what a target such as -14 LUFS is measured against. */
  integrated: number;
  /** Over the last 400 ms. */
  momentary: number;
  /** Over the last 3 s. */
  shortTerm: number;
}

/**
 * Reads loudness block by block: `add` takes the K-weighted mean square of
 * the next 100 ms, summed over the channels, as the meter's processor posts
 * it, and gives the loudness up to it. The integrated loudness counts every
 * 400 ms window that passes the gates of BS.1770 (-70 LUFS, then 10 LU under
 * the loudness of the rest): it agrees with `measureLoudness` on a whole
 * sound. `clear` starts it over; the momentary and short-term loudness go on.
 */
export function createLoudnessReader() {
  const recent: number[] = [];
  let windows: number[] = [];
  let since = 0;
  return {
    add: (block: number): LiveLoudness => {
      recent.push(block);
      if (recent.length > SHORT_TERM_BLOCKS) {
        recent.shift();
      }
      since += 1;
      const window =
        recent.length >= WINDOW_BLOCKS ? mean(recent.slice(-WINDOW_BLOCKS)) : 0;
      // A window counts once it is made of blocks since the last clear.
      if (since >= WINDOW_BLOCKS && window > ABSOLUTE_GATE) {
        windows.push(window);
      }
      const gate = windows.length > 0 ? mean(windows) * RELATIVE_GATE : 0;
      const loud = windows.filter((power) => power > gate);
      return {
        integrated:
          loud.length > 0 ? lufsOf(mean(loud)) : Number.NEGATIVE_INFINITY,
        momentary: lufsOf(window),
        shortTerm:
          recent.length === SHORT_TERM_BLOCKS
            ? lufsOf(mean(recent))
            : Number.NEGATIVE_INFINITY,
      };
    },
    clear: () => {
      windows = [];
      since = 0;
    },
  };
}

const PROCESSOR = "audioui-loudness";

/**
 * The meter's processor: it K-weights each channel of its input (a high
 * shelf, then a high-pass, with the coefficients `@audio/weighting-k` gives
 * for the context's rate), and posts the mean square of each block of 100 ms,
 * summed over the channels. A quantum with no input counts as silence. It has
 * no output, so what it measures is never heard through it.
 */
export const LOUDNESS_WORKLET = `class LoudnessMeter extends AudioWorkletProcessor {
  constructor(options) {
    super();
    const { coefs, frames } = options.processorOptions;
    this.shelf = coefs[0];
    this.highpass = coefs[1];
    this.frames = frames;
    this.states = [];
    this.sum = 0;
    this.count = 0;
  }
  filter(state, x) {
    const s = this.shelf;
    const h = this.highpass;
    const u = s.b0 * x + state[0];
    state[0] = s.b1 * x - s.a1 * u + state[1];
    state[1] = s.b2 * x - s.a2 * u;
    const y = h.b0 * u + state[2];
    state[2] = h.b1 * u - h.a1 * y + state[3];
    state[3] = h.b2 * u - h.a2 * y;
    return y;
  }
  process(inputs) {
    const input = inputs[0] || [];
    const length = input.length > 0 ? input[0].length : 128;
    while (this.states.length < input.length) {
      this.states.push(new Float64Array(4));
    }
    for (let i = 0; i < length; i++) {
      for (let c = 0; c < input.length; c++) {
        const y = this.filter(this.states[c], input[c][i]);
        this.sum += y * y;
      }
      this.count++;
      if (this.count === this.frames) {
        this.port.postMessage(this.sum / this.frames);
        this.sum = 0;
        this.count = 0;
        // A filter left ringing into silence would reach the subnormal numbers, which are slow.
        for (const state of this.states) {
          for (let k = 0; k < 4; k++) {
            if (Math.abs(state[k]) < 1e-30) state[k] = 0;
          }
        }
      }
    }
    return true;
  }
}
registerProcessor("${PROCESSOR}", LoudnessMeter);`;

/** A live loudness meter on a context, as `createLoudnessMeter` makes it. */
export interface LoudnessMeter {
  /** Starts the integrated loudness over, from the next block. */
  clear: () => void;
  dispose: () => void;
  /** Connect what to measure here, in stereo: a mono input is in both channels. It is only listened to, never heard. */
  readonly input: AudioNode;
}

/**
 * Measures what is connected to it while it plays, on the audio thread, and
 * calls `onLoudness` with its momentary, short-term and integrated loudness
 * every 100 ms. `null` when the context cannot run worklets.
 */
export async function createLoudnessMeter(
  ctx: BaseAudioContext,
  onLoudness: (loudness: LiveLoudness) => void
): Promise<LoudnessMeter | null> {
  if (!(await loadWorklet(ctx, LOUDNESS_WORKLET))) {
    return null;
  }
  const node = new AudioWorkletNode(ctx, PROCESSOR, {
    channelCount: 2,
    channelCountMode: "explicit",
    channelInterpretation: "speakers",
    numberOfInputs: 1,
    numberOfOutputs: 0,
    processorOptions: {
      coefs: kWeighting.coefs(ctx.sampleRate),
      frames: Math.round(ctx.sampleRate / 10),
    },
  });
  const reader = createLoudnessReader();
  node.port.onmessage = (event: MessageEvent<number>) =>
    onLoudness(reader.add(event.data));
  return {
    clear: reader.clear,
    dispose: () => {
      node.port.onmessage = null;
      node.port.close();
    },
    input: node,
  };
}

/**
 * Waveform and spectrum reduction, pure and audio-only: PCM samples to the
 * peaks a waveform draws (the lowest and highest sample of each slice, or one
 * amplitude per slice), and a live analyser's spectrum to frequency bands.
 * Decoding a file is the caller's: `AudioContext.decodeAudioData` gives the
 * samples these take.
 */

/** The lowest and highest sample of each slice of the audio, -1 to 1: what the Waveform draws as the waveform really is, lopsided where the audio is. */
export interface AudioPeaks {
  max: Float32Array;
  min: Float32Array;
}

/** Reduces PCM samples to `bucketCount` slices, keeping each slice's lowest and highest sample across every channel, a take panned hard to one side still draws, rather than reading as a flat line on the channel it isn't on. Compute it once per file, at a resolution above the widest waveform you expect (a few thousand slices); the Waveform fits it to its width and to any `range`. */
export function computePeaks(
  channels: readonly ArrayLike<number>[],
  bucketCount: number
): AudioPeaks {
  const count = Math.max(0, Math.floor(bucketCount));
  const min = new Float32Array(count);
  const max = new Float32Array(count);
  let length = 0;
  for (const channel of channels) {
    length = Math.max(length, channel.length);
  }
  if (count === 0 || length === 0) {
    return { max, min };
  }
  for (let bucket = 0; bucket < count; bucket += 1) {
    const start = Math.floor((bucket * length) / count);
    const end = Math.max(
      start + 1,
      Math.floor(((bucket + 1) * length) / count)
    );
    let low = 0;
    let high = 0;
    for (const channel of channels) {
      for (
        let index = start;
        index < end && index < channel.length;
        index += 1
      ) {
        const sample = channel[index] ?? 0;
        // A sample that is not a number (a corrupt decode) draws as silence.
        if (Number.isFinite(sample)) {
          low = Math.min(low, sample);
          high = Math.max(high, sample);
        }
      }
    }
    min[bucket] = low;
    max[bucket] = high;
  }
  return { max, min };
}

/** Scales peaks so the loudest sample, either way, reaches full height, keeping each slice's lopsidedness. */
export function normalizePeaks(peaks: AudioPeaks): AudioPeaks {
  let loudest = 0;
  for (const value of peaks.max) {
    loudest = Math.max(loudest, Math.abs(value));
  }
  for (const value of peaks.min) {
    loudest = Math.max(loudest, Math.abs(value));
  }
  if (loudest === 0) {
    return peaks;
  }
  return {
    max: peaks.max.map((value) => value / loudest),
    min: peaks.min.map((value) => value / loudest),
  };
}

/** Downsamples raw PCM samples into `targetLength` blocks, each block's value the peak (max) absolute amplitude within it, the reduction waveform visualizers use, since a block average flattens short transients into a softer-looking curve than the audio actually has. The blocks share the samples out evenly and cover every one: the last is not left short, and a target longer than the audio repeats its samples rather than reading past them. */
export function downsampleWaveform(
  samples: ArrayLike<number>,
  targetLength: number
): number[] {
  const count = Math.floor(targetLength);
  if (!(count > 0) || samples.length === 0) {
    return [];
  }
  const blocks: number[] = [];
  for (let block = 0; block < count; block += 1) {
    const start = Math.floor((block * samples.length) / count);
    const end = Math.max(
      start + 1,
      Math.floor(((block + 1) * samples.length) / count)
    );
    let peak = 0;
    for (let index = start; index < end && index < samples.length; index += 1) {
      const value = Math.abs(samples[index] ?? 0);
      if (Number.isFinite(value) && value > peak) {
        peak = value;
      }
    }
    blocks.push(peak);
  }
  return blocks;
}

/** Scales `values` so the largest entry becomes 1, keeps a waveform's peak reaching full height regardless of the source audio's own loudness. */
export function normalizeWaveform(values: number[]): number[] {
  // A loop, not `Math.max(...values)`: a long enough array overflows the stack.
  let peak = 0;
  for (const value of values) {
    if (Number.isFinite(value) && value > peak) {
      peak = value;
    }
  }
  if (peak === 0) {
    return values.map(() => 0);
  }
  return values.map((value) => value / peak);
}

/** The frequencies and levels `spectrumBands` spreads its bands over. */
export interface SpectrumBandsOptions {
  /** The level drawn as 1, in decibels: `AnalyserNode.maxDecibels`. @default -30 */
  maxDb?: number;
  /** Highest frequency of the last band, in Hz. @default 12000 */
  maxHz?: number;
  /** The level drawn as 0, in decibels: `AnalyserNode.minDecibels`. @default -100 */
  minDb?: number;
  /** Lowest frequency of the first band, in Hz. @default 60 */
  minHz?: number;
  /** Sample rate of the audio the spectrum was taken from, in Hz. */
  sampleRate: number;
}

/** Reduces an analyser's spectrum (`getFloatFrequencyData`: decibels per frequency bin) to `bands.length` levels of 0-1, low to high, written into `bands`. Bands are spaced evenly on a log scale between `minHz` and `maxHz`, the way pitch is heard, so the low end isn't crammed into one bar, and each takes its loudest bin, so a single note still lights its band. */
export function spectrumBands(
  spectrum: ArrayLike<number>,
  bands: Float32Array,
  {
    maxDb = -30,
    maxHz = 12_000,
    minDb = -100,
    minHz = 60,
    sampleRate,
  }: SpectrumBandsOptions
): Float32Array {
  const binCount = spectrum.length;
  if (
    binCount === 0 ||
    !(Number.isFinite(sampleRate) && sampleRate > 0) ||
    !(minHz > 0) ||
    !(maxDb > minDb)
  ) {
    return bands.fill(0);
  }
  const hzPerBin = sampleRate / 2 / binCount;
  const octaves = Math.log2(Math.max(maxHz, minHz + 1) / minHz);
  for (let band = 0; band < bands.length; band += 1) {
    const lowHz = minHz * 2 ** ((octaves * band) / bands.length);
    const highHz = minHz * 2 ** ((octaves * (band + 1)) / bands.length);
    const first = Math.min(binCount - 1, Math.floor(lowHz / hzPerBin));
    const last = Math.min(
      binCount,
      Math.max(first + 1, Math.ceil(highHz / hzPerBin))
    );
    let loudestDb = minDb;
    for (let bin = first; bin < last; bin += 1) {
      const level = spectrum[bin] ?? minDb;
      if (!Number.isNaN(level)) {
        loudestDb = Math.max(loudestDb, level);
      }
    }
    bands[band] = Math.min(1, (loudestDb - minDb) / (maxDb - minDb));
  }
  return bands;
}

import yin from "@audio/pitch-yin";

/** A signal's loudness as an RMS level, from 0 to 1. */
const rms = (samples: Float32Array) => {
  let energy = 0;
  for (const sample of samples) {
    energy += sample * sample;
  }
  return Math.sqrt(energy / samples.length);
};

/** What a detection found: the pitch and how periodic the sound is there. */
export interface PitchEstimate {
  confidence: number;
  frequency: number;
}

/** What `detectPitch` looks for. */
export interface DetectPitchOptions {
  /** The highest pitch looked for, in hertz. */
  maxHz: number;
  /** The lowest pitch looked for, in hertz: lower costs more, and needs at least two of its periods in the samples. */
  minHz: number;
  /** How quiet the signal may be, as an RMS level from 0 to 1, before nothing is detected. */
  minLevel: number;
  /** YIN's threshold: how aperiodic a period may be and still count. Lower is stricter. */
  threshold: number;
}

/** The pitch the samples hold and how clear it is, or nothing: too quiet a signal, or no clear period. */
export function detectPitch(
  samples: Float32Array,
  sampleRate: number,
  { maxHz, minHz, minLevel, threshold }: DetectPitchOptions
): PitchEstimate | null {
  if (rms(samples) < minLevel) {
    return null;
  }
  const heard = yin(samples, {
    fs: sampleRate,
    maxFreq: maxHz,
    minFreq: minHz,
    threshold,
  });
  return heard ? { confidence: heard.clarity, frequency: heard.freq } : null;
}

import detectBeat from "@audio/beat-detect";
import chroma from "@audio/mir-chroma";
import { detectTransients, type TempoEstimate } from "./beat";

/** What a recording's beat is read as when it comes in: its tempo, if it has one, and its transients, in seconds. */
export interface BeatAnalysis {
  estimate: TempoEstimate | null;
  transients: number[];
}

/** How near a grid's beat a transient falls to count for it, in beats: first loosely, then closely. */
const GRID_REACHES = [1 / 8, 1 / 16];
/** How many transients a grid needs to be fitted on. */
const FIT_POINTS = 8;

/** How many of `transients` fall within an eighth of a beat of a grid of `period` seconds from `start`. */
function alignedCount(
  transients: readonly number[],
  start: number,
  period: number
): number {
  let count = 0;
  for (const time of transients) {
    const beat = Math.round((time - start) / period);
    if (Math.abs(time - (start + beat * period)) < period / 8) {
      count += 1;
    }
  }
  return count;
}

/**
 * The grid of `bpm` from `firstBeat`, fitted on the transients near its
 * beats: its phase is the one that lines up the most of them, and its beat
 * the slope of a least-squares line through them, read twice, the second
 * time nearer. A tempo read in whole BPM, as 128 for 127.3, would drift a
 * third of a second a minute; fitted, it holds to the sample.
 */
function fittedGrid(
  bpm: number,
  firstBeat: number,
  transients: readonly number[]
): { bpm: number; firstBeat: number } {
  let period = 60 / bpm;
  let start = firstBeat;
  let most = alignedCount(transients, start, period);
  for (const time of transients) {
    if (time > firstBeat + 8 * period) {
      break;
    }
    const count = alignedCount(transients, time, period);
    if (count > most) {
      most = count;
      start = time;
    }
  }
  for (const reach of GRID_REACHES) {
    const beats: number[] = [];
    const times: number[] = [];
    for (const time of transients) {
      const beat = Math.round((time - start) / period);
      if (Math.abs(time - (start + beat * period)) < reach * period) {
        beats.push(beat);
        times.push(time);
      }
    }
    if (beats.length < FIT_POINTS) {
      break;
    }
    const meanBeat = beats.reduce((sum, beat) => sum + beat, 0) / beats.length;
    const meanTime = times.reduce((sum, time) => sum + time, 0) / times.length;
    let covariance = 0;
    let spread = 0;
    for (const [index, beat] of beats.entries()) {
      covariance += (beat - meanBeat) * ((times[index] as number) - meanTime);
      spread += (beat - meanBeat) ** 2;
    }
    const slope = covariance / spread;
    // A slope far from the beat read is a fit gone astray: the grid stays as it is.
    if (!(slope > 0 && Math.abs(slope / period - 1) < 0.02)) {
      break;
    }
    period = slope;
    start = meanTime - slope * meanBeat;
  }
  start -= Math.floor(start / period) * period;
  return { bpm: 60 / period, firstBeat: start };
}

/** The window a recording's chroma is read on, in samples: a power of two, as the FFT takes, near 0.17 s at 48 kHz. */
const CHROMA_WINDOW = 8192;
/** A window quieter than this, as a mean square, is silence: it says nothing of the key. */
const CHROMA_SILENCE = 1e-6;

/**
 * How much of a recording's sound lies in each pitch class, C to B, summing
 * to 1, read once as it is decoded: what a key is read from, with notes or
 * without (`detectKeys` of the Scale menu). Its channels mixed, it is the
 * chroma of `@audio/mir-chroma` on each window that is not silence, averaged.
 * All zeros for a recording that is all silence.
 */
export function audioChroma(
  channels: readonly Float32Array[],
  sampleRate: number
): number[] {
  const length = channels[0]?.length ?? 0;
  const sum = new Array<number>(12).fill(0);
  const mix = new Float32Array(CHROMA_WINDOW);
  let frames = 0;
  for (let at = 0; at + CHROMA_WINDOW <= length; at += CHROMA_WINDOW) {
    let energy = 0;
    for (let frame = 0; frame < CHROMA_WINDOW; frame += 1) {
      let sample = 0;
      for (const channel of channels) {
        sample += channel[at + frame] as number;
      }
      sample /= channels.length;
      mix[frame] = sample;
      energy += sample * sample;
    }
    if (energy / CHROMA_WINDOW >= CHROMA_SILENCE) {
      const read = chroma(mix, { fs: sampleRate });
      for (let pitchClass = 0; pitchClass < 12; pitchClass += 1) {
        sum[pitchClass] = (sum[pitchClass] as number) + (read[pitchClass] ?? 0);
      }
      frames += 1;
    }
  }
  return frames > 0 ? sum.map((value) => value / frames) : sum;
}

/**
 * Reads a recording's beat, once, as it is decoded: what `warpOnImport` warps
 * its clips by. `@audio/beat-detect` reads its tempo, which finds the beat of
 * real playing; the grid is then fitted on the transients, to the sample.
 * A sound with no attack (silence, noise, a single hit read with no
 * confidence) has no tempo.
 */
export function analyzeBeat(
  channels: readonly Float32Array[],
  sampleRate: number
): BeatAnalysis {
  const [first] = channels;
  let mix = first ?? new Float32Array(0);
  if (channels.length > 1) {
    mix = new Float32Array(mix.length);
    for (const channel of channels) {
      for (const [index, sample] of channel.entries()) {
        mix[index] = (mix[index] as number) + sample / channels.length;
      }
    }
  }
  const read = detectBeat(mix, { fs: sampleRate });
  const [firstBeat] = read.beats;
  if (
    !(
      read.bpm > 0 &&
      read.confidence > 0 &&
      read.onsets.length > 0 &&
      firstBeat !== undefined
    )
  ) {
    return { estimate: null, transients: [] };
  }
  const transients = detectTransients(channels, sampleRate);
  return {
    estimate: {
      confidence: read.confidence,
      ...fittedGrid(read.bpm, firstBeat, transients),
    },
    transients,
  };
}

import { detectKeys } from "../pitch/key";
import type { Scale } from "../pitch/scale";
import { peakDb, rmsDb } from "./level";
import { type Loudness, measureLoudness } from "./loudness";
import { analyzeBeat, audioChroma } from "./recording";
import { detectSilences } from "./silence";

/** What ACX asks of an audiobook: the RMS between -23 and -18 dBFS, the peak at most -3 dBFS, the noise floor at most -60 dBFS RMS. */
export const ACX = {
  maxNoiseFloor: -60,
  maxPeak: -3,
  maxRms: -18,
  minRms: -23,
} as const;

/** One requirement and how the sound stands against it. */
export interface AcxCheck {
  pass: boolean;
  /** The measured level in dB, or `null` when the sound has nothing to measure it on. */
  value: number | null;
}

/** A sound against the ACX audiobook requirements. */
export interface AcxReport {
  /** The level of the quietest pause of at least half a second, in dBFS RMS: `null` for a sound with no such pause. */
  noiseFloor: AcxCheck;
  pass: boolean;
  peak: AcxCheck;
  rms: AcxCheck;
}

/** The RMS of every channel together, in dBFS: the power of each averaged. */
function rmsAll(channels: readonly Float32Array[]): number {
  if (channels.length === 0) {
    return Number.NEGATIVE_INFINITY;
  }
  const power =
    channels.reduce((sum, channel) => sum + 10 ** (rmsDb(channel) / 10), 0) /
    channels.length;
  return power > 0 ? 10 * Math.log10(power) : Number.NEGATIVE_INFINITY;
}

/**
 * Checks a sound against ACX's requirements for an audiobook. The noise floor
 * is read on the quietest pause of at least half a second: a sound with none
 * cannot be measured, and does not pass.
 */
export function checkAcx(
  channels: readonly Float32Array[],
  sampleRate: number
): AcxReport {
  const rms = rmsAll(channels);
  const peak = Math.max(
    Number.NEGATIVE_INFINITY,
    ...channels.map((channel) => peakDb(channel))
  );
  let floor: number | null = null;
  for (const [from, to] of detectSilences(channels, sampleRate, {
    minDuration: 0.5,
  })) {
    const level = rmsAll(
      channels.map((channel) =>
        channel.subarray(
          Math.floor(from * sampleRate),
          Math.ceil(to * sampleRate)
        )
      )
    );
    floor = floor === null ? level : Math.min(floor, level);
  }
  const report = {
    noiseFloor: {
      pass: floor !== null && floor <= ACX.maxNoiseFloor,
      value: floor,
    },
    peak: { pass: peak <= ACX.maxPeak, value: peak },
    rms: { pass: rms >= ACX.minRms && rms <= ACX.maxRms, value: rms },
  };
  return {
    ...report,
    pass: report.noiseFloor.pass && report.peak.pass && report.rms.pass,
  };
}

/** What `reportSound` reads from a sound. */
export interface SoundReport {
  acx: AcxReport;
  duration: number;
  /** The likeliest key, or `null` for a sound with too little pitched content. */
  key: Scale | null;
  loudness: Loudness;
  /** The tempo in beats a minute, or `null` for a sound with no beat. */
  tempo: number | null;
}

/**
 * Reads a sound once, to tell what it is: its loudness, its key, its tempo,
 * and whether it meets ACX's requirements. It reads every sample, a few
 * seconds a minute of stereo on a laptop, so call it where the page can wait.
 */
export function reportSound(
  channels: readonly Float32Array[],
  sampleRate: number
): SoundReport {
  const [key] = detectKeys([], 1, audioChroma(channels, sampleRate));
  return {
    acx: checkAcx(channels, sampleRate),
    duration: (channels[0]?.length ?? 0) / sampleRate,
    key: key ?? null,
    loudness: measureLoudness(channels, sampleRate),
    tempo: analyzeBeat(channels, sampleRate).estimate?.bpm ?? null,
  };
}

import { dbToGain, gainToDb } from "./level";

/** Frames a block of the scan holds: a pause is found to one of them. */
const BLOCK = 1024;
/** The loudest a pause gets, as a waveform's ground drawn flat at any zoom but the closest, in dBFS. */
const GROUND_DB = gainToDb(0.02);
/** How far under the loudest sample a quiet recording's pauses are, in dB. */
const UNDER_PEAK_DB = 20;
/** The shortest pause, in seconds: a gap between two sounds of a phrase is shorter. */
const SHORTEST = 0.06;

/** What `detectSilences` takes, both optional. */
export interface SilenceOptions {
  /** The shortest stretch that counts as a pause, in seconds. @default 0.06 */
  minDuration?: number;
  /** The loudest a sample of a pause gets, in dBFS. @default -34 dBFS, or 20 dB under the loudest sample when that is lower */
  threshold?: number;
}

/** The loudest sample of each block, across the channels, and of them all. */
function blockPeaks(channels: readonly Float32Array[], length: number) {
  const loudest = new Float32Array(Math.ceil(length / BLOCK));
  let peak = 0;
  for (const channel of channels) {
    for (let index = 0; index < channel.length; index += 1) {
      const level = Math.abs(channel[index] as number);
      const block = Math.floor(index / BLOCK);
      if (level > (loudest[block] as number)) {
        loudest[block] = level;
      }
      peak = Math.max(peak, level);
    }
  }
  return { loudest, peak };
}

/**
 * Where `channels` pause between their sounds, as `[from, to]` in seconds, in
 * order: each stretch of at least `minDuration` where every sample of every
 * channel stays under the threshold, found to a block of 1024 frames. As a
 * text's spaces between its words, these are what a selection by sound
 * stops at.
 */
export function detectSilences(
  channels: readonly Float32Array[],
  sampleRate: number,
  options: SilenceOptions = {}
): [number, number][] {
  const length = channels[0]?.length ?? 0;
  if (length === 0 || !(sampleRate > 0)) {
    return [];
  }
  const { loudest, peak } = blockPeaks(channels, length);
  const blocks = loudest.length;
  const threshold = dbToGain(
    options.threshold ?? Math.min(GROUND_DB, gainToDb(peak) - UNDER_PEAK_DB)
  );
  const shortest = options.minDuration ?? SHORTEST;
  const found: [number, number][] = [];
  let start: number | null = null;
  for (let block = 0; block <= blocks; block += 1) {
    const quiet = block < blocks && (loudest[block] as number) <= threshold;
    if (quiet && start === null) {
      start = block;
    } else if (!quiet && start !== null) {
      const from = (start * BLOCK) / sampleRate;
      const to = Math.min(block * BLOCK, length) / sampleRate;
      if (to - from >= shortest) {
        found.push([from, to]);
      }
      start = null;
    }
  }
  return found;
}

import { stftAnalyse } from "@audio/stft";

/**
 * A recording summed up as spectra, for a spectrogram drawn on the GPU that
 * does not hold the recording: a column every `hop` frames, each bin's level
 * from DC to Nyquist over windows of `size` frames, a byte each. This is the
 * form `gl-spectrogram` takes them in, and `LaneSamples.spectra` of
 * `@audio-ui/gl/lane`.
 */
export interface Spectra {
  hop: number;
  /** A byte a bin, `size / 2 + 1` a column, column after column: (dB + 150) · 1.6, 0 dB a full-scale sine on its bin, 0 silence. */
  levels: Uint8Array;
  size: number;
}

/** The frames of a window of the spectra, and of one of their columns: 2048, some 43 ms at 48 kHz, the window a spectrogram fits a view with. */
export const SPECTRA_SIZE = 2048;

/** A level as the spectra keep it: a byte, (dB + 150) · 1.6, 0 for silence. */
const LEVEL_SCALE = 1.6;
const LEVEL_FLOOR = 150;

/** The frames read at a time while the spectra are made: whole columns, with a frame of the page between each read. */
const SPECTRA_READ = 1 << 20;

/** A mean power, a full-scale sine on its bin being 1, as the byte the spectra keep. */
const levelByte = (power: number) =>
  power > 0
    ? Math.min(
        255,
        Math.max(
          0,
          Math.round((10 * Math.log10(power) + LEVEL_FLOOR) * LEVEL_SCALE)
        )
      )
    : 0;

/** A reader of a recording, mixed to one: how many frames it holds, and its frames from `from` to `to`, at once or later. */
export interface SpectraSource {
  frames: number;
  read: (
    from: number,
    to: number
  ) => ArrayLike<number> | Promise<ArrayLike<number>>;
}

/**
 * The spectra of a recording (`Spectra`): a column every `hop` frames, each
 * bin's power over the Hann windows of `size` frames centred in the column
 * every `size / 2` frames (the short-time transform of `@audio/stft`), their
 * mean, as a byte. Silence lies before and after the recording. Read from
 * `source` a stretch at a time, with a frame of the page between each, so it
 * can run on the page or, for a long recording, in a worker; made once, as the
 * recording is written, and kept beside it. `size` is a power of two and
 * `hop` a multiple of `size / 2`.
 */
export async function spectrogramSpectra(
  source: SpectraSource,
  {
    hop = SPECTRA_SIZE,
    size = SPECTRA_SIZE,
  }: { hop?: number; size?: number } = {}
): Promise<Spectra> {
  const bins = size / 2 + 1;
  const half = size / 2;
  const columns = Math.ceil(source.frames / hop);
  const levels = new Uint8Array(columns * bins);
  const windows = Math.max(1, hop / half);
  // A full-scale sine on its bin: |X| is a quarter of the window, squared.
  const full = windows * (size / 4) ** 2;
  const each = Math.max(1, Math.floor(SPECTRA_READ / hop));
  // The power of the columns of one read, summed over their windows.
  const power = new Float64Array(each * bins);
  const readFrom = async (first: number): Promise<void> => {
    if (first >= columns) {
      return;
    }
    const last = Math.min(columns, first + each);
    // The first window of a column starts a quarter of a window before it, the windows half a window apart.
    const from = first * hop - half / 2;
    const to = last * hop + half / 2;
    // What lies inside the recording is read; before and after it is silence.
    const start = Math.max(0, from);
    const end = Math.min(source.frames, to);
    const read = await source.read(start, end);
    const frames = new Float32Array(to - from);
    power.fill(0);
    for (let at = start; at < end; at += 1) {
      frames[at - from] = (read[at - start] as number | undefined) ?? 0;
    }
    stftAnalyse(
      frames,
      (magnitude, _phase, position) => {
        const column = Math.floor((from + position + half) / hop);
        if (column < first || column >= last) {
          return;
        }
        for (let bin = 0; bin < bins; bin += 1) {
          const at = (column - first) * bins + bin;
          power[at] = (power[at] as number) + (magnitude[bin] as number) ** 2;
        }
      },
      { frameSize: size, hopSize: half }
    );
    for (let at = 0; at < (last - first) * bins; at += 1) {
      levels[first * bins + at] = levelByte((power[at] as number) / full);
    }
    await new Promise((resolve) => setTimeout(resolve));
    await readFrom(last);
  };
  await readFrom(0);
  return { hop, levels, size };
}

/**
 * Turns what an `AnalyserNode` reports into what a plot draws: a spectrum with
 * as many points as you ask for, spread evenly along a logarithmic frequency
 * axis, the way an equalizer's x axis runs. An analyser's bins are spread
 * evenly in hertz, so most of them crowd above 2 kHz and the low end gets a
 * handful; here each point takes the loudest bin it covers, and below the
 * resolution of the analyser a point reads between the two bins around it.
 */

/** The quietest a point is drawn: what a silent bin, `-Infinity` dB, becomes. */
export const SPECTRUM_FLOOR_DB = -140;

/** The frequencies the axis of `logSpectrum` spans. */
export interface LogSpectrumOptions {
  /** Highest frequency on the axis. @default 20000 */
  maxHz?: number;
  /** Lowest frequency on the axis. @default 20 */
  minHz?: number;
}

/**
 * Fills `out` with `bins` (dB per analyser bin, as `getFloatFrequencyData`
 * writes them) resampled onto a log axis. `sampleRate` is the context's.
 * Returns `out`, so a caller can keep and publish one array.
 */
export function logSpectrum(
  bins: ArrayLike<number>,
  sampleRate: number,
  out: Float32Array,
  { maxHz = 20_000, minHz = 20 }: LogSpectrumOptions = {}
): Float32Array {
  const count = out.length;
  // Without bins, a sample rate or an axis there is nothing to read: silence.
  if (
    !(
      bins.length > 0 &&
      Number.isFinite(sampleRate) &&
      sampleRate > 0 &&
      minHz > 0 &&
      maxHz > minHz
    )
  ) {
    return out.fill(SPECTRUM_FLOOR_DB);
  }
  const binWidth = sampleRate / (bins.length * 2);
  const ratio = maxHz / minHz;
  /** The frequency a position along the axis, in points, falls at. */
  const hzAt = (point: number) =>
    minHz * ratio ** (point / Math.max(count - 1, 1));
  const dbAt = (bin: number) => {
    const value =
      bins[Math.min(bins.length - 1, Math.max(0, bin))] ?? SPECTRUM_FLOOR_DB;
    return Number.isFinite(value)
      ? Math.max(value, SPECTRUM_FLOOR_DB)
      : SPECTRUM_FLOOR_DB;
  };

  for (let point = 0; point < count; point += 1) {
    const from = hzAt(point - 0.5) / binWidth;
    const to = hzAt(point + 0.5) / binWidth;
    const first = Math.ceil(from);
    const last = Math.floor(to);
    if (last >= first) {
      let loudest = SPECTRUM_FLOOR_DB;
      for (let bin = first; bin <= last; bin += 1) {
        loudest = Math.max(loudest, dbAt(bin));
      }
      out[point] = loudest;
    } else {
      // Narrower than a bin: read between the two around the point's centre.
      const centre = hzAt(point) / binWidth;
      const below = Math.floor(centre);
      const share = centre - below;
      out[point] = dbAt(below) * (1 - share) + dbAt(below + 1) * share;
    }
  }
  return out;
}

/** How long `holdPeaks` holds a peak, and how fast it lets it fall. */
export interface PeakHoldOptions {
  /** How fast a peak falls once its hold is over, in dB per second. @default 24 */
  fall?: number;
  /** How long a peak stays put before it falls, in seconds. @default 1 */
  hold?: number;
}

/**
 * Keeps the loudest level each point of a spectrum reached: a peak rises with
 * the spectrum at once, stays put for `hold` seconds, then falls at `fall` dB
 * per second until the spectrum meets it again. `peaks` and `holding` (seconds
 * of hold left per point) are updated in place, `elapsed` seconds after the
 * last call. Returns `peaks`.
 */
export function holdPeaks(
  spectrum: ArrayLike<number>,
  peaks: Float32Array,
  holding: Float32Array,
  elapsed: number,
  { fall = 24, hold = 1 }: PeakHoldOptions = {}
): Float32Array {
  // A clock that stood still or went back cannot make a peak fall or hold longer.
  const dt = Number.isFinite(elapsed) ? Math.max(0, elapsed) : 0;
  for (let point = 0; point < peaks.length; point += 1) {
    const level = spectrum[point] ?? SPECTRUM_FLOOR_DB;
    const peak = peaks[point] ?? SPECTRUM_FLOOR_DB;
    const left = holding[point] ?? 0;
    if (level >= peak) {
      peaks[point] = level;
      holding[point] = hold;
    } else if (left > 0) {
      holding[point] = left - dt;
    } else {
      peaks[point] = Math.max(level, peak - fall * dt);
    }
  }
  return peaks;
}

/**
 * How alike the two channels of a sound are, from -1 to 1, as a correlation
 * meter reads it: 1 when both carry the same sound (mono, at any levels), 0
 * when they have nothing in common or only one side sounds, and -1 when one is
 * the other upside down, which cancels out once the two are summed to mono.
 * Over the samples both channels have; 0 for silence, never `NaN`.
 */
export function stereoCorrelation(
  left: ArrayLike<number>,
  right: ArrayLike<number>
): number {
  const length = Math.min(left.length, right.length);
  let both = 0;
  let leftEnergy = 0;
  let rightEnergy = 0;
  for (let index = 0; index < length; index += 1) {
    const l = left[index] as number;
    const r = right[index] as number;
    both += l * r;
    leftEnergy += l * l;
    rightEnergy += r * r;
  }
  const scale = Math.sqrt(leftEnergy * rightEnergy);
  return scale > 0 && Number.isFinite(scale)
    ? Math.max(-1, Math.min(1, both / scale))
    : 0;
}

import {
  cascade,
  process as filterSection,
  highpass,
  lowpass,
  state,
} from "@audio/biquad";
import crossover from "@audio/eq-crossover";

/** What each slice of a sound is made of: the share of its lows, mids and highs, the loudest of the three being 1. */
export interface BandShares {
  high: Float32Array;
  low: Float32Array;
  mid: Float32Array;
}

/** Where the lows end and the highs begin, in hertz. */
const LOW_UNDER = 250;
const HIGH_OVER = 2500;

/**
 * Reads a sound as `count` slices of equal length, each by how its energy is
 * spread over three bands: the lows under 250 Hz, the highs over 2.5 kHz and
 * the mids between. It is what colours a waveform by its frequencies, a drum
 * low and a hat high. Channels are mixed to one; silence is all zeros. It
 * reads every sample once for each band.
 */
export function bandShares(
  channels: readonly Float32Array[],
  sampleRate: number,
  count: number
): BandShares {
  const length = channels[0]?.length ?? 0;
  const mix = new Float32Array(length);
  for (const channel of channels) {
    for (let index = 0; index < length; index += 1) {
      mix[index] =
        (mix[index] as number) + (channel[index] as number) / channels.length;
    }
  }
  const low = Float32Array.from(mix);
  filterSection(low, lowpass(LOW_UNDER, Math.SQRT1_2, sampleRate));
  const high = Float32Array.from(mix);
  filterSection(high, highpass(HIGH_OVER, Math.SQRT1_2, sampleRate));
  const shares: BandShares = {
    high: new Float32Array(count),
    low: new Float32Array(count),
    mid: new Float32Array(count),
  };
  for (let slice = 0; slice < count; slice += 1) {
    const from = Math.floor((slice * length) / count);
    const to = Math.max(from + 1, Math.floor(((slice + 1) * length) / count));
    let l = 0;
    let m = 0;
    let h = 0;
    for (let index = from; index < to && index < length; index += 1) {
      const lo = low[index] as number;
      const hi = high[index] as number;
      const mi = (mix[index] as number) - lo - hi;
      l += lo * lo;
      m += mi * mi;
      h += hi * hi;
    }
    const top = Math.max(l, m, h);
    if (top > 1e-12) {
      shares.low[slice] = Math.sqrt(l / top);
      shares.mid[slice] = Math.sqrt(m / top);
      shares.high[slice] = Math.sqrt(h / top);
    }
  }
  return shares;
}

/** A sound as three signals: what it has under 250 Hz, between, and over 2.5 kHz. */
export interface SplitBands {
  high: Float32Array;
  low: Float32Array;
  mid: Float32Array;
  /** The loudest sample of each band, 0 to 1: draw each as tall as its own loudest reaches, so a band that is quiet in the mix still shows. */
  peaks: { high: number; low: number; mid: number };
}

/** The three bands of a stretch of sound: its lows under 250 Hz, its highs over 2.5 kHz, and the mids between. */
export interface Bands {
  high: Float32Array;
  low: Float32Array;
  mid: Float32Array;
}

/**
 * Splits a sound in three a stretch at a time, as `splitBands` does: each call
 * takes the stretch that follows the one before and carries the crossover's
 * state over, so stretches split in order are the sound split whole. Start
 * another for another sound, or to read from somewhere else: a stretch read on
 * its own settles once some tens of milliseconds have gone through.
 */
export function createBandSplit(
  sampleRate: number
): (stretch: ArrayLike<number>) => Bands {
  const bands = crossover([LOW_UNDER, HIGH_OVER], 4, sampleRate);
  const [lowBand = [], midBand = [], highBand = []] = bands;
  const kept = [lowBand, midBand, highBand].map((sections) =>
    sections.map(() => state())
  );
  const through = (
    stretch: ArrayLike<number>,
    sections: Parameters<typeof cascade>[1],
    states: ReturnType<typeof state>[] | undefined
  ) => {
    const out = Float32Array.from(stretch);
    cascade(out, sections, states);
    return out;
  };
  return (stretch) => ({
    high: through(stretch, highBand, kept[2]),
    low: through(stretch, lowBand, kept[0]),
    mid: through(stretch, midBand, kept[1]),
  });
}

/**
 * The sound's channels mixed to one and split in three by a Linkwitz-Riley
 * crossover (`@audio/eq-crossover`, 24 dB an octave) at 250 Hz and 2.5 kHz:
 * the three bands add back to the mix, level and phase. Draw each as a
 * waveform of its own to colour a sound by its frequencies, as DJ software
 * does; `bandShares` is the same split read as shares per slice. It holds
 * three copies of the mix, so call it when a view asks for it; a sound too
 * long to hold is split a stretch at a time by `createBandSplit`.
 */
export function splitBands(
  channels: readonly Float32Array[],
  sampleRate: number
): SplitBands {
  const length = channels[0]?.length ?? 0;
  const mix = new Float32Array(length);
  for (const channel of channels) {
    for (let index = 0; index < length; index += 1) {
      mix[index] =
        (mix[index] as number) + (channel[index] as number) / channels.length;
    }
  }
  const { high, low, mid } = createBandSplit(sampleRate)(mix);
  const loudest = (values: Float32Array) =>
    values.reduce((top, value) => Math.max(top, Math.abs(value)), 0);
  return {
    high,
    low,
    mid,
    peaks: { high: loudest(high), low: loudest(low), mid: loudest(mid) },
  };
}
